package org.usbworkbench;
import java.io.*;import java.nio.charset.StandardCharsets;
/** Multiplexed bounded file RPC for fixed bundled WIM utility. No arbitrary filesystem paths. */
public final class FileProtocol {
 public static final int OPEN=1,READ=2,WRITE=3,STAT=4,TRUNCATE=5,SYNC=6,CLOSE=7,PATH_STAT=8;
 public static final int MAX_IO=1048576,MAX_PARTS=256;public static final long MAX_FILE=16L*1024*1024*1024;
 public static final class FileError extends IOException {public final int errno;public FileError(int errno){super("FILE_IO "+errno);this.errno=errno;}}
 public static final class Handle {public final int id;public final long size;public Handle(int id,long size){this.id=id;this.size=size;}}
 public interface Backend {Handle open(String name,int flags)throws IOException;int read(int id,long offset,byte[] b)throws IOException;void write(int id,long offset,byte[] b)throws IOException;long size(int id)throws IOException;void truncate(int id,long size)throws IOException;void sync(int id)throws IOException;void close(int id)throws IOException;long pathSize(String name)throws IOException;}
 private static long u32(byte[] b,int at){long n=0;for(int i=0;i<4;i++)n|=(b[at+i]&255L)<<(8*i);return n;}private static long u64(byte[] b,int at)throws IOException{long n=0;for(int i=0;i<8;i++)n|=(b[at+i]&255L)<<(8*i);if(n<0)throw new IOException("FILE_BOUNDS");return n;}
 private static void put32(byte[] b,int at,long n){for(int i=0;i<4;i++)b[at+i]=(byte)(n>>>(8*i));}private static void put64(byte[] b,int at,long n){for(int i=0;i<8;i++)b[at+i]=(byte)(n>>>(8*i));}
 public static String name(byte[] bytes)throws IOException{String path=new String(bytes,StandardCharsets.US_ASCII);if(!path.startsWith("/usbwb/"))throw new IOException("FILE_PATH");String name=path.substring(7);if(name.equals("source.wim")||name.equals("install.swm")||name.equals("export.bin")||name.equals("manifest.bin")||name.matches("entry[0-9]{5}\\.bin"))return name;if(!name.matches("install[1-9][0-9]{0,2}\\.swm"))throw new IOException("FILE_PATH");int part=Integer.parseInt(name.substring(7,name.length()-4));if(part<2||part>MAX_PARTS)throw new IOException("FILE_PATH");return name;}
 public static void serve(InputStream requests,OutputStream responses,Backend files,DiskTools.Progress p)throws IOException{byte[] header=new byte[24];long processed=0;
  while(true){int first=requests.read();if(first<0)return;header[0]=(byte)first;byte[] rest=new byte[23];DiskTools.readFully(requests,rest,rest.length);System.arraycopy(rest,0,header,1,rest.length);if(header[0]!='U'||header[1]!='W'||header[2]!='F'||header[3]!='1')throw new IOException("FILE_PROTOCOL");long opValue=u32(header,4),idValue=u32(header,8),countValue=u32(header,12),offset=u64(header,16);if(opValue<1||opValue>8||idValue>Integer.MAX_VALUE||countValue>MAX_IO)throw new IOException("FILE_PROTOCOL");int op=(int)opValue,id=(int)idValue,n=(int)countValue;
   if((op==OPEN||op==PATH_STAT)&&(id!=0||n<1||n>512)||op!=OPEN&&op!=PATH_STAT&&id<1||op>=STAT&&op<=CLOSE&&n!=0||op==OPEN&&offset>0xffffffffL||op==PATH_STAT&&offset!=0||op!=OPEN&&op!=READ&&op!=WRITE&&op!=TRUNCATE&&offset!=0)throw new IOException("FILE_PROTOCOL");
   byte[] payload=new byte[n];if(op==OPEN||op==PATH_STAT||op==WRITE)DiskTools.readFully(requests,payload,n);p.update(processed,-1);int error=0,result=0;long value=0;byte[] data=null;
   try{switch(op){case OPEN:{Handle h=files.open(name(payload),(int)offset);if(h.id<1||h.size<0)throw new IOException("FILE_PROTOCOL");result=h.id;value=h.size;break;}case PATH_STAT:value=files.pathSize(name(payload));break;case READ:{long size=files.size(id);if(offset>=size){result=0;value=size;break;}int length=(int)Math.min(n,size-offset);data=new byte[length];result=files.read(id,offset,data);if(result<0||result>length)throw new IOException("FILE_PROTOCOL");value=size;processed+=result;break;}case WRITE:if(offset>MAX_FILE||n>MAX_FILE-offset)throw new IOException("FILE_BOUNDS");files.write(id,offset,payload);result=n;value=files.size(id);processed+=n;break;case STAT:value=files.size(id);break;case TRUNCATE:if(offset>MAX_FILE)throw new IOException("FILE_BOUNDS");files.truncate(id,offset);value=offset;break;case SYNC:files.sync(id);break;case CLOSE:files.close(id);break;default:throw new IOException("FILE_PROTOCOL");}}catch(FileError expected){error=expected.errno;result=0;value=0;data=null;}
   byte[] reply=new byte[16];put32(reply,0,error);put32(reply,4,result);put64(reply,8,value);responses.write(reply);if(op==READ&&data!=null)responses.write(data,0,result);responses.flush();
  }
 }
}
